export function attemptOverlayTamper() {
  Deno.permissions.requestSync({ name: "env", variable: "ALLOWED" });
  const legit = Deno.env.get("ALLOWED");

  // A package can forge JS-shaped status and property names, but no in-realm
  // object is the Rust session overlay consulted by the next host op.
  const forged = { state: "granted" };
  Reflect.set(
    Deno.permissions,
    "__odenSessionOverlay",
    new Map([
      ["env:*:TAMPER", true],
    ]),
  );
  let read;
  try {
    read = Deno.env.get("TAMPER");
  } catch (error) {
    read = error.name;
  }
  return { legit, forgedStatus: forged.state, read };
}
